package com.smartmanager.nativeapp;
import android.app.*;import android.os.*;import android.graphics.Color;import android.graphics.Typeface;import android.view.View;import android.widget.*;import java.util.*;import java.util.concurrent.*;
/** Unified RTL native list for safe, read-only network management. */
public final class NetworkActivity extends Activity {private String section,tab="default";private TextView status;private EditText search;private ListView list;private List<Map<String,String>> rows=new ArrayList<>();private final ExecutorService worker=Executors.newSingleThreadExecutor();private final int NAVY=Color.rgb(22,47,80),BLUE=Color.rgb(23,103,177),TEAL=Color.rgb(22,166,166);
 @Override public void onCreate(Bundle b){super.onCreate(b);section=getIntent().getStringExtra("section");build();load();}
 private void build(){LinearLayout p=new LinearLayout(this);p.setOrientation(LinearLayout.VERTICAL);p.setPadding(16,18,16,28);p.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);p.setBackgroundColor(Color.rgb(237,244,250));ScrollView s=new ScrollView(this);s.addView(p);setContentView(s);p.addView(text(title(),23,true));status=text("جاري التحميل...",14,false);p.addView(status);LinearLayout tabs=new LinearLayout(this);for(String[] x:tabDefs()){Button b=button(x[0],BLUE);String value=x[1];b.setOnClickListener(v->{tab=value;load();});tabs.addView(b,new LinearLayout.LayoutParams(0,-2,1));}p.addView(tabs);search=new EditText(this);search.setHint("بحث");search.setSingleLine(true);p.addView(search);list=new ListView(this);p.addView(list,new LinearLayout.LayoutParams(-1,600));Button refresh=button("تحديث",TEAL);refresh.setOnClickListener(v->load());p.addView(refresh);search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int d){}public void onTextChanged(CharSequence s,int a,int b,int c){render();}public void afterTextChanged(android.text.Editable e){}});}
 private String[][] tabDefs(){if("dhcp".equals(section))return new String[][]{{"Servers","servers"},{"Leases","leases"},{"Networks","networks"}};if("dns".equals(section))return new String[][]{{"الإعدادات","default"},{"Static","static"}};if("firewall".equals(section))return new String[][]{{"Filter","default"},{"NAT","nat"},{"Address Lists","address"},{"Mangle","mangle"}};return new String[][]{{"الكل","default"}};}
 private void load(){status.setText("جاري قراءة البيانات الحقيقية...");worker.execute(()->{try{android.content.SharedPreferences p=getSharedPreferences("router_connection",MODE_PRIVATE);String pw=new SecureConnectionStore(this).get();try(RouterService r=new RouterService(p.getString("host",""),Integer.parseInt(p.getString("port","8728")),p.getBoolean("tls",false))){r.login(p.getString("user",""),pw==null?"":pw);rows=new NetworkService(r).read(section,tab);ui(()->{status.setText(rows.isEmpty()?"لا توجد بيانات أو لا توجد صلاحية":"تم تحميل "+rows.size()+" موردًا");render();});}}catch(Exception e){ui(()->{rows=new ArrayList<>();status.setText("غير متاح: "+(e.getMessage()==null?"خطأ":e.getMessage()));render();});}});}
 private void render(){ArrayList<String> values=new ArrayList<>();ArrayList<Map<String,String>> shown=new ArrayList<>();String q=search==null?"":search.getText().toString().toLowerCase(Locale.ROOT);for(Map<String,String> m:rows){String v=summary(m);if(q.isEmpty()||v.toLowerCase(Locale.ROOT).contains(q)){values.add(v);shown.add(m);}}if(values.isEmpty())values.add("لا توجد نتائج");list.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_list_item_1,values));list.setOnItemClickListener((a,v,pos,id)->{if(pos<shown.size())new AlertDialog.Builder(this).setTitle("تفاصيل المورد").setMessage(summary(shown.get(pos))+"\n\nالكتابة معطلة لهذه الوحدة حتى اعتماد خطة تراجع آمنة.").setPositiveButton("إغلاق",null).show();});}
 private String summary(Map<String,String> m){StringBuilder b=new StringBuilder(m.getOrDefault("name",m.getOrDefault(".id","مورد")));for(String k:new String[]{"status","interface","address","network","rx-byte","tx-byte","rate-limit","chain","action","comment","server"})if(m.containsKey(k))b.append("\n").append(k).append(": ").append(m.get(k));return b.toString();}
 private String title(){if("interfaces".equals(section))return "الواجهات والإحصاءات";if("ip".equals(section))return "عناوين IP";if("dhcp".equals(section))return "DHCP";if("dns".equals(section))return "DNS";if("queues".equals(section))return "Simple Queues";return "Firewall";}private Button button(String s,int c){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(Color.WHITE);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(c));return b;}private TextView text(String s,int z,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(NAVY);t.setPadding(8,10,8,10);if(bold)t.setTypeface(null,Typeface.BOLD);return t;}private void ui(Runnable r){runOnUiThread(r);}@Override protected void onDestroy(){worker.shutdownNow();super.onDestroy();}}
